import json
import re
import subprocess
from datetime import datetime, timezone
from pathlib import Path

README_PATH = Path("README.md")
OUTPUT_PATH = Path("web-validation.json")

MD_LINK_RE = re.compile(r'(!?)\[([^\]]+)\]\((https?://[^)\s]+)\)')
HREF_RE = re.compile(r'href=["\'](https?://[^"\']+)["\']')
H2_RE = re.compile(r"^##\s+(.+)$")
H3_RE = re.compile(r"^###\s+(.+)$")


def strip_html_comments(text: str) -> str:
    return re.sub(r"<!--.*?-->", "", text, flags=re.S)


def extract_links_from_readme(path: Path) -> list[dict]:
    if not path.exists():
        raise FileNotFoundError(f"README not found: {path}")

    content = strip_html_comments(path.read_text(encoding="utf-8"))
    links_by_url: dict[str, dict] = {}
    current_h2 = "Uncategorized"
    current_h3 = ""

    for line_no, line in enumerate(content.splitlines(), start=1):
        h2_match = H2_RE.match(line.strip())
        if h2_match:
            current_h2 = h2_match.group(1).strip()
            current_h3 = ""
            continue

        h3_match = H3_RE.match(line.strip())
        if h3_match:
            current_h3 = h3_match.group(1).strip()
            continue

        section = f"{current_h2} / {current_h3}" if current_h3 else current_h2

        for match in MD_LINK_RE.finditer(line):
            is_image = match.group(1) == "!"
            label = match.group(2).strip()
            url = match.group(3).strip()
            if is_image:
                continue
            links_by_url.setdefault(
                url,
                {
                    "name": label,
                    "url": url,
                    "section": section,
                    "line": line_no,
                    "source": "markdown",
                },
            )

        for match in HREF_RE.finditer(line):
            url = match.group(1).strip()
            links_by_url.setdefault(
                url,
                {
                    "name": url,
                    "url": url,
                    "section": section,
                    "line": line_no,
                    "source": "html",
                },
            )

    return list(links_by_url.values())


def check_url(url: str, timeout_seconds: int = 12) -> tuple[str, str, str]:
    # Follow redirects and report final status/effective URL.
    result = subprocess.run(
        [
            "curl",
            "-sS",
            "-o",
            "/dev/null",
            "-w",
            "%{http_code}||%{url_effective}||%{redirect_url}",
            "-L",
            "--max-time",
            str(timeout_seconds),
            url,
        ],
        capture_output=True,
        text=True,
        timeout=timeout_seconds + 5,
    )
    output = result.stdout.strip()
    parts = output.split("||")
    status_code = parts[0] if len(parts) > 0 else "000"
    final_url = parts[1] if len(parts) > 1 and parts[1] else url
    redirect_url = parts[2] if len(parts) > 2 else ""
    return status_code, final_url, redirect_url


def main() -> int:
    links = extract_links_from_readme(README_PATH)
    results = {"healthy": [], "redirects": [], "broken": [], "at_risk": []}

    for item in links:
        name = item["name"]
        url = item["url"]
        section = item["section"]
        line_no = item["line"]
        print(f"Checking {name}...")

        try:
            status_code, final_url, redirect_url = check_url(url)

            base_entry = {
                "name": name,
                "url": url,
                "final_url": final_url,
                "section": section,
                "line": line_no,
            }

            if status_code.startswith("2"):
                if final_url != url:
                    results["redirects"].append(
                        {
                            **base_entry,
                            "status": "redirect",
                            "status_code": int(status_code),
                            "redirect_url": redirect_url or final_url,
                        }
                    )
                else:
                    results["healthy"].append(
                        {
                            **base_entry,
                            "status": "healthy",
                            "status_code": int(status_code),
                        }
                    )
            elif status_code.startswith("3"):
                results["redirects"].append(
                    {
                        **base_entry,
                        "status": "redirect",
                        "status_code": int(status_code),
                        "redirect_url": redirect_url or final_url,
                    }
                )
            elif status_code in {"404", "410"}:
                results["broken"].append(
                    {
                        **base_entry,
                        "status": "broken",
                        "status_code": int(status_code),
                        "reason": f"HTTP {status_code}",
                    }
                )
            elif status_code == "000":
                results["broken"].append(
                    {
                        **base_entry,
                        "status": "broken",
                        "reason": "Connection failed or timeout",
                    }
                )
            else:
                results["at_risk"].append(
                    {
                        **base_entry,
                        "status": "at_risk",
                        "status_code": int(status_code),
                        "reason": f"HTTP {status_code}",
                    }
                )
        except subprocess.TimeoutExpired:
            results["at_risk"].append(
                {
                    "name": name,
                    "url": url,
                    "section": section,
                    "line": line_no,
                    "status": "at_risk",
                    "reason": "Timeout",
                }
            )
        except Exception as exc:
            results["at_risk"].append(
                {
                    "name": name,
                    "url": url,
                    "section": section,
                    "line": line_no,
                    "status": "at_risk",
                    "reason": str(exc)[:120],
                }
            )

    summary = {
        "checked_at": datetime.now(timezone.utc).isoformat(),
        "total": len(links),
        "healthy": len(results["healthy"]),
        "redirects": len(results["redirects"]),
        "broken": len(results["broken"]),
        "at_risk": len(results["at_risk"]),
    }
    results["summary"] = summary

    OUTPUT_PATH.write_text(json.dumps(results, indent=2), encoding="utf-8")
    print(json.dumps(summary, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3

from __future__ import annotations

import json
import os
import re
import subprocess
import sys
from pathlib import Path


# Keep this validator focused on low-risk structural checks. Repository fit stays a human decision.
REQUIRED_BODY_SECTIONS = (
    "Section",
    "Why this belongs",
    "Primary documented web-agent use case",
    "Public reference",
    "Affiliation disclosure",
)

ALLOWED_SECTIONS = {
    "Autonomous Web Agents",
    "Computer-use Agents",
    "AI Web Automation Tools",
    "Dev Tools",
    "AI Web Scrapers/Crawlers",
    "Web Search & Query Tools",
    "Benchmarks & Research",
    "Tutorials & Guides",
    "Archive",
}

ITEM_LINE_RE = re.compile(r"^- \[(?P<name>[^\]]+)\]\((?P<url>https?://[^)]+)\) - (?P<rest>.+)$")
ITEM_SUBMISSION_PREFIXES = ("Add: ", "Archive: ")
ITEM_SUBMISSION_FILES = {"README.md", "ARCHIVE.md"}


def run_git(*args: str) -> str:
    result = subprocess.run(
        ["git", *args],
        check=True,
        capture_output=True,
        text=True,
    )
    return result.stdout


def load_pull_request_event() -> dict | None:
    event_path = os.environ.get("GITHUB_EVENT_PATH")
    if not event_path:
        return None

    event = json.loads(Path(event_path).read_text(encoding="utf-8"))
    return event.get("pull_request")


def changed_files(base_sha: str) -> set[str]:
    diff = run_git("diff", "--name-only", f"{base_sha}...HEAD")
    return {line.strip() for line in diff.splitlines() if line.strip()}


def item_key(item_line: str) -> tuple[str, str] | None:
    match = ITEM_LINE_RE.match(item_line)
    if not match:
        return None
    return match.group("name").strip(), match.group("url").strip()


def new_items_in_diff(diff: str) -> list[str]:
    new_lines: list[str] = []
    changed_keys: set[tuple[str, str]] = set()
    for line in diff.splitlines():
        if line.startswith(("+++", "---")):
            continue
        if re.match(r"^\+- \[", line):
            new_lines.append(line[1:])
        elif re.match(r"^-- \[", line):
            key = item_key(line[1:])
            if key:
                changed_keys.add(key)
    # A rewritten line for an item that was already listed is an edit, not a submission.
    return [line for line in new_lines if item_key(line) not in changed_keys]


def added_item_lines(base_sha: str) -> list[tuple[str, str]]:
    added: list[tuple[str, str]] = []
    for path in ("README.md", "ARCHIVE.md"):
        diff = run_git("diff", "--unified=0", f"{base_sha}...HEAD", "--", path)
        added.extend((path, line) for line in new_items_in_diff(diff))
    return added


def extract_body_sections(body: str) -> dict[str, str]:
    sections: dict[str, str] = {}
    for heading in REQUIRED_BODY_SECTIONS:
        # Some clients send the pull request body with CRLF line endings.
        pattern = re.compile(
            rf"(?ms)^## {re.escape(heading)}\r?\n+(.*?)(?=^## |\Z)"
        )
        match = pattern.search(body)
        if match:
            sections[heading] = match.group(1).strip()
    return sections


def normalize_markdown_line(value: str) -> str:
    return re.sub(r"\s+", " ", value.strip())


def normalize_section(value: str) -> str:
    value = re.sub(r"^[-*]\s*", "", value.strip(), flags=re.MULTILINE)
    first_line = value.splitlines()[0].strip()
    return first_line


def detect_section(path: str, item_line: str) -> str | None:
    if path == "ARCHIVE.md":
        return "Archive"

    lines = Path(path).read_text(encoding="utf-8").splitlines()
    normalized_item_line = normalize_markdown_line(item_line)
    item_index = None
    for index, line in enumerate(lines):
        if normalize_markdown_line(line) == normalized_item_line:
            item_index = index
            break
    if item_index is None:
        return None

    for index in range(item_index - 1, -1, -1):
        line = lines[index]
        if line.startswith("### "):
            return line[4:].strip()
        if line.startswith("## "):
            return line[3:].strip()
    return None


def main() -> int:
    pull_request = load_pull_request_event()
    if not pull_request:
        print("No pull_request event detected. Skipping contribution validation.")
        return 0

    base_sha = pull_request["base"]["sha"]
    title = (pull_request.get("title") or "").strip()
    body = pull_request.get("body") or ""
    pr_files = changed_files(base_sha)

    is_explicit_item_submission = title.startswith(ITEM_SUBMISSION_PREFIXES)
    is_minimal_item_edit = bool(pr_files) and pr_files.issubset(ITEM_SUBMISSION_FILES)
    if not is_explicit_item_submission and not is_minimal_item_edit:
        print("PR is not an item submission. Skipping contribution validation.")
        return 0

    added_items = added_item_lines(base_sha)
    if not added_items:
        print("No new list item detected in README.md or ARCHIVE.md. Skipping contribution validation.")
        return 0

    errors: list[str] = []

    if len(added_items) != 1:
        errors.append("New item submissions must add exactly one list item per PR.")
        item_path = None
        item_line = None
    else:
        item_path, item_line = added_items[0]

    expected_prefix = "Add: "
    if len(added_items) == 1 and item_path == "ARCHIVE.md":
        expected_prefix = "Archive: "

    if not title.startswith(expected_prefix):
        errors.append(f'PR title must start with "{expected_prefix}" for this kind of submission.')

    sections = extract_body_sections(body)
    for heading in REQUIRED_BODY_SECTIONS:
        if not sections.get(heading):
            errors.append(f'PR body must include a non-empty "## {heading}" section.')

    declared_section = normalize_section(sections.get("Section", "")) if sections.get("Section") else ""
    if declared_section and declared_section not in ALLOWED_SECTIONS:
        errors.append("PR body section must match one of the repository section names exactly.")

    public_reference = sections.get("Public reference", "")
    if public_reference and not re.search(r"https?://", public_reference):
        errors.append('The "Public reference" section must include a public URL.')

    if len(added_items) == 1:
        match = ITEM_LINE_RE.match(item_line)
        if not match:
            errors.append("Added item line must follow the standard awesome-list format.")
        else:
            name = match.group("name").strip()
            url = match.group("url").strip()
            rest = match.group("rest").strip()
            description = re.sub(r"\s+!\[.*$", "", rest).strip()

            if not description or not description[0].isupper():
                errors.append("Item descriptions must begin with a capital letter.")
            if not description.endswith("."):
                errors.append("Item descriptions must end with a period.")

            actual_section = detect_section(item_path, item_line)
            if not actual_section:
                errors.append("Could not determine which section contains the added item.")
            elif declared_section and declared_section != actual_section:
                errors.append(
                    f'PR body says section "{declared_section}", but the item was added under "{actual_section}".'
                )

            repo_text = "\n".join(
                Path(path).read_text(encoding="utf-8") for path in ("README.md", "ARCHIVE.md") if Path(path).exists()
            )
            if repo_text.count(f"- [{name}](") > 1:
                errors.append(f'The item name "{name}" already exists in the repository list.')
            if repo_text.count(f"]({url})") > 1:
                errors.append(f'The URL "{url}" already exists in the repository list.')

    if errors:
        print("Contribution policy validation failed:")
        for error in errors:
            print(f"- {error}")
        return 1

    print("Contribution policy validation passed.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

import json
import os
import re
import sys
from datetime import datetime, timedelta, timezone
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

README_PATH = Path("README.md")
OUTPUT_PATH = Path("github-validation.json")
RAW_OUTPUT_PATH = Path("github-raw-results.json")
REPO_URL_RE = re.compile(r"https?://github\.com/([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+)")


def extract_repos_from_readme(path: Path) -> list[str]:
    if not path.exists():
        raise FileNotFoundError(f"README not found: {path}")

    text = path.read_text(encoding="utf-8")
    repos: set[str] = set()
    for match in REPO_URL_RE.finditer(text):
        owner = match.group(1)
        repo = match.group(2)
        repos.add(f"{owner}/{repo}")
    return sorted(repos)


def parse_github_datetime(value: str | None) -> datetime | None:
    if not value:
        return None
    try:
        return datetime.strptime(value, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def github_api_get_repo(repo: str, token: str | None) -> tuple[int | None, dict, dict]:
    url = f"https://api.github.com/repos/{repo}"
    headers = {
        "Accept": "application/vnd.github+json",
        "User-Agent": "awesome-web-agents-validator",
    }
    if token:
        headers["Authorization"] = f"Bearer {token}"

    req = Request(url, headers=headers)
    try:
        with urlopen(req, timeout=15) as resp:
            body = resp.read().decode("utf-8")
            data = json.loads(body) if body else {}
            return resp.status, data, dict(resp.headers.items())
    except HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        try:
            data = json.loads(body) if body else {}
        except json.JSONDecodeError:
            data = {"message": body[:200]}
        return exc.code, data, dict(exc.headers.items())
    except URLError as exc:
        return None, {"message": str(exc.reason)}, {}


def main() -> int:
    token = os.environ.get("GITHUB_TOKEN")
    repos = extract_repos_from_readme(README_PATH)
    results = {"healthy": [], "stale": [], "broken": [], "at_risk": []}
    raw_results: list[dict] = []

    one_year_ago = datetime.now(timezone.utc) - timedelta(days=365)
    rate_limit_reset_epoch: int | None = None

    for repo in repos:
        print(f"Checking {repo}...")

        if rate_limit_reset_epoch is not None:
            reset_dt = datetime.fromtimestamp(rate_limit_reset_epoch, tz=timezone.utc).isoformat()
            item = {
                "name": repo,
                "url": f"https://github.com/{repo}",
                "status": "at_risk",
                "reason": f"GitHub API rate limited until {reset_dt}",
            }
            results["at_risk"].append(item)
            raw_results.append(item)
            continue

        status_code, data, response_headers = github_api_get_repo(repo, token)
        url = f"https://github.com/{repo}"

        if status_code == 200:
            archived = bool(data.get("archived", False))
            stars = data.get("stargazers_count", 0)
            pushed_at = data.get("pushed_at")
            open_issues = data.get("open_issues_count", 0)
            description = (data.get("description") or "")[:100]
            last_commit = parse_github_datetime(pushed_at)

            item = {
                "name": repo,
                "url": url,
                "archived": archived,
                "stars": stars,
                "last_commit": pushed_at,
                "open_issues": open_issues,
                "description": description,
            }

            if archived:
                item["status"] = "stale"
                item["reason"] = "Repo is archived"
                results["stale"].append(item)
            elif last_commit and last_commit < one_year_ago:
                item["status"] = "stale"
                item["reason"] = f"No commits for over 1 year (last: {pushed_at[:10]})"
                results["stale"].append(item)
            else:
                item["status"] = "healthy"
                results["healthy"].append(item)

            raw_results.append(item)
            continue

        if status_code == 404:
            item = {
                "name": repo,
                "url": url,
                "status": "broken",
                "reason": "Repo not found or deleted",
            }
            results["broken"].append(item)
            raw_results.append(item)
            continue

        remaining = response_headers.get("X-RateLimit-Remaining")
        reset = response_headers.get("X-RateLimit-Reset")
        if status_code in (403, 429) and remaining == "0" and reset:
            try:
                rate_limit_reset_epoch = int(reset)
            except ValueError:
                rate_limit_reset_epoch = None
            reset_text = (
                datetime.fromtimestamp(rate_limit_reset_epoch, tz=timezone.utc).isoformat()
                if rate_limit_reset_epoch is not None
                else "unknown"
            )
            item = {
                "name": repo,
                "url": url,
                "status": "at_risk",
                "reason": f"GitHub API rate limit exceeded (resets at {reset_text})",
            }
            results["at_risk"].append(item)
            raw_results.append(item)
            continue

        message = data.get("message", "API error")
        item = {
            "name": repo,
            "url": url,
            "status": "at_risk",
            "reason": f"API error ({status_code}): {str(message)[:120]}",
        }
        results["at_risk"].append(item)
        raw_results.append(item)

    summary = {
        "total": len(repos),
        "healthy": len(results["healthy"]),
        "stale": len(results["stale"]),
        "broken": len(results["broken"]),
        "at_risk": len(results["at_risk"]),
    }
    results["summary"] = summary

    OUTPUT_PATH.write_text(json.dumps(results, indent=2), encoding="utf-8")
    RAW_OUTPUT_PATH.write_text(json.dumps(raw_results, indent=2), encoding="utf-8")
    print(json.dumps(summary, indent=2))

    if summary["at_risk"] > 0:
        print(
            "Hint: set GITHUB_TOKEN to avoid unauthenticated rate limits, e.g. "
            "GITHUB_TOKEN=$(gh auth token) python scripts/validate_github.py",
            file=sys.stderr,
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
